static int branch(TargetCoreType*c,uint32 i){uint64 a=c->reg.x[RS1(i)],b=c->reg.x[RS2(i)];int t=0;switch(F3(i)){case 0:t=a==b;break;case 1:t=a!=b;break;case 4:t=(sint64)a<(sint64)b;break;case 5:t=(sint64)a>=(sint64)b;break;case 6:t=a<b;break;case 7:t=a>=b;break;}if(!t)return next(c,i);{uint64 d=c->reg.pc+imm_b(i);if(d&3U){riscv_raise_exception(c,0,d);return RISCV_EXEC_TRAP;}c->reg.pc=d;}return RISCV_EXEC_RETIRED;}
