static int load(TargetCoreType*c,uint32 i){uint64 a=c->reg.x[RS1(i)]+imm_i(i),v=0;uint32 lo,hi;uint16 h;uint8 b;unsigned f=F3(i),z=(f==0||f==4)?1:(f==1||f==5)?2:(f==2||f==6)?4:8;if(a&(z-1U))return memory_fault(c,a,4);if(!riscv_pmp_check(c,a,z,CpuMemoryAccess_READ))return memory_fault(c,a,5);if(z==1){if(bus_get_data8(c->core_id,a,&b)!=STD_E_OK)return memory_fault(c,a,5);v=b;}else if(z==2){if(bus_get_data16(c->core_id,a,&h)!=STD_E_OK)return memory_fault(c,a,5);v=h;}else{if(bus_get_data32(c->core_id,a,&lo)!=STD_E_OK)return memory_fault(c,a,5);v=lo;if(z==8){if(bus_get_data32(c->core_id,a+4,&hi)!=STD_E_OK)return memory_fault(c,a,5);v|=(uint64)hi<<32;}}if(f==0)v=SEXT(v,8);else if(f==1)v=SEXT(v,16);else if(f==2)v=SEXT(v,32);c->reg.x[RD(i)]=v;return next(c,i);}
