static int system_trap(TargetCoreType*c,uint32 i){riscv_raise_exception(c,i==MATCH_EBREAK?3:11,0);return RISCV_EXEC_TRAP;}
static int mret(TargetCoreType*c,uint32 i){uint64 s=c->reg.csr.mstatus,t=c->reg.csr.mepc;(void)i;if(t&3U){riscv_raise_exception(c,0,t);return RISCV_EXEC_TRAP;}c->reg.privilege=(RiscvPrivilege)((s>>11)&3U);s=(s&~(1ULL<<3))|(((s>>7)&1U)<<3)|(1ULL<<7);s&=~(3ULL<<11);c->reg.csr.mstatus=s;c->reg.pc=t;return RISCV_EXEC_RETIRED;}
static int wfi(TargetCoreType*c,uint32 i){c->is_halt=TRUE;return next(c,i);}
static uint64*csr_ptr(TargetCoreType*c,unsigned n){if(n>=0x3b0&&n<=0x3bf)return&c->reg.csr.pmpaddr[n-0x3b0];switch(n){case 0x100:return&c->reg.csr.sstatus;case 0x104:return&c->reg.csr.sie;case 0x105:return&c->reg.csr.stvec;case 0x106:return&c->reg.csr.scounteren;case 0x140:return&c->reg.csr.sscratch;case 0x141:return&c->reg.csr.sepc;case 0x142:return&c->reg.csr.scause;case 0x143:return&c->reg.csr.stval;case 0x144:return&c->reg.csr.sip;case 0x180:return&c->reg.csr.satp;case 0x300:return&c->reg.csr.mstatus;case 0x301:return&c->reg.csr.misa;case 0x302:return&c->reg.csr.medeleg;case 0x303:return&c->reg.csr.mideleg;case 0x304:return&c->reg.csr.mie;case 0x305:return&c->reg.csr.mtvec;case 0x306:return&c->reg.csr.mcounteren;case 0x30a:return&c->reg.csr.menvcfg;case 0x340:return&c->reg.csr.mscratch;case 0x341:return&c->reg.csr.mepc;case 0x342:return&c->reg.csr.mcause;case 0x343:return&c->reg.csr.mtval;case 0x344:return&c->reg.csr.mip;case 0x3a0:return&c->reg.csr.pmpcfg[0];case 0x3a2:return&c->reg.csr.pmpcfg[1];case 0xB00:return&c->reg.csr.mcycle;case 0xB02:return&c->reg.csr.minstret;case 0xF14:return&c->reg.csr.mhartid;default:return 0;}}
